solutionCode:
function reverse(s) {
  let r = '';
  for (let i = s.length - 1; i >= 0; i--) {
    r += s[i];
  }
  return r;
}
module.exports = { reverse };

testHarness:
const { reverse } = require('./solution.js');

const cases = [
  { label: '"hello"', input: 'hello', expected: 'olleh' },
  { label: '"a"', input: 'a', expected: 'a' },
  { label: '""', input: '', expected: '' },
  { label: '"racecar"', input: 'racecar', expected: 'racecar' },
];

for (const c of cases) {
  try {
    const actual = reverse(c.input);
    if (actual === c.expected) {
      console.log(`PASS\t${c.label}`);
    } else {
      console.log(`FAIL\t${c.label}\t"${c.expected}"\t"${actual}"`);
    }
  } catch (e) {
    console.log(`ERROR\t${c.label}\t${e.name}: ${e.message}`);
  }
}
